```cpp
// Building a label-to-index map — especially useful if you're
// doing this lookup repeatedly
std::unordered_map<wxString, int> BuildColumnMap(wxGrid* grid)
{
    std::unordered_map<wxString, int> columnMap;

    for (int col = 0; col < grid->GetNumberCols(); col++)
    {
        columnMap[grid->GetColLabelValue(col)] = col;
    }

    return columnMap;
}

// Usage becomes rather clean...
void SomeMethod(wxGrid* grid)
{
    auto colMap = BuildColumnMap(grid);
    int row = 3; // whichever row interests you

    // Now the intent reads almost like plain language
    if (colMap.count("Revenue") > 0)
    {
        wxString value = grid->GetCellValue(row, colMap["Revenue"]);
        wxLogDebug("Revenue at row %d: %s", row, value);
    }
}
