console.log("║       ~ Element Investigation ~      ║");
console.log("╚══════════════════════════════════════╝");
console.log(`\n🔎 Looking for: "${result.searchValue}" (${result.searchType})`);
console.log(`📦 Array contains types: [${result.arrayTypes}]`);
