// RegistrationService.java
// This is where things get interesting...
import org.mindrot.jbcrypt.BCrypt;
import java.util.HashMap;
import java.util.Map;
import java.util.regex.Pattern;

public class RegistrationService {

    // I chose a HashMap here, but you might find
    // a database connection more... compelling
    private Map<String, User> userStore = new HashMap<>();

    private static final Pattern EMAIL_PATTERN = 
        Pattern.compile("^[A-Za-z0-9+_.-]+@(.+)$");

    private static final Pattern PASSWORD_PATTERN =
        Pattern.compile("^(?=.*[A-Z])(?=.*[0-9])(?=.*[@#$%]).{8,}$");

    public RegistrationResult register(
            String name, 
            String email, 
            String password) {

        // Validation - each check tells a story
        if (!isValidName(name)) {
            return RegistrationResult.failure(
                "Name seems a bit... off. Try again?");
        }

        if (!isValidEmail(email)) {
            return RegistrationResult.failure(
                "That email address raises some questions...");
        }

        if (!isValidPassword(password)) {
            return RegistrationResult.failure(
                "Password needs more character — uppercase, " +
                "number, and special character (@#$%)");
        }

        if (userStore.containsKey(email.toLowerCase())) {
            return RegistrationResult.failure(
                "This email already has a story here...");
        }

        // BCrypt — because security deserves elegance
        String hashedPassword = BCrypt.hashpw(
            password, BCrypt.gensalt(12));

        User newUser = new User(
            name, 
            email.toLowerCase(), 
            hashedPassword);

        userStore.put(email.toLowerCase(), newUser);

        return RegistrationResult.success(newUser);
    }

    private boolean isValidName(String name) {
        return name != null && 
               !name.trim().isEmpty() && 
               name.length() >= 2;
    }

    private boolean isValidEmail(String email) {
        return email != null && 
               EMAIL_PATTERN.matcher(email).matches();
    }

    private boolean isValidPassword(String password) {
        return password != null && 
               PASSWORD_PATTERN.matcher(password).matches();
    }
}
