# Binary String XOR Substring Finder

*[Leaning back thoughtfully, sketching something on a notepad]*

Interesting puzzle... there's a certain elegance hiding in here if you look at it from the right angle. The key insight? `val ^ first = second` means `val = first ^ second`. So we're really just hunting for substrings whose decimal value equals a precomputed target. Let the precomputation do the heavy lifting...

*[Slides the solution across the desk]*

```pascal
program BinaryStringXORQueries;

{$APPTYPE CONSOLE}

uses
  SysUtils, Generics.Collections;

type
  TIntPair = record
    Left, Right: Integer;
  end;

  TResultArray = array of TIntPair;
  TQuery = array of Integer;
  TQueries = array of TQuery;

// Precompute all substring decimal values and store the shortest
// (minimum left endpoint) occurrence for each value
function FindSubstringIndices(const S: string; 
  const Queries: TQueries): TResultArray;
var
  N, I, J, QueryCount: Integer;
  Target, Val: Int64;
  Map: TDictionary<Int64, TIntPair>;
  Pair: TIntPair;
  MaxBits: Integer;
begin
  N := Length(S);
  QueryCount := Length(Queries);
  SetLength(Result, QueryCount);

  // A gentle hint to ourselves: values beyond 10^9 can't match
  // since first, second <= 10^9, so val = first XOR second <= ~2*10^9
  // But substrings > 30 bits will exceed this... worth noting
  MaxBits := 30; // 2^30 > 10^9, so substrings longer than 30 chars won't matter

  // Build our value -> [left, right] map
  // For each starting position, accumulate bits rightward
  Map := TDictionary<Int64, TIntPair>.Create;
  try
    for I := 1 to N do  // 1-indexed for Pascal strings
    begin
      Val := 0;
      for J := I to N do
      begin
        // Shift and add current bit
        Val := (Val shl 1) or (Ord(S[J]) - Ord('0'));

        // Subtle optimization: no need to go further if value exceeds our range
        if Val > 2000000000 then
          Break;

        // Only store if not already found (first occurrence = minimum left)
        // Shortest first: we visit by length implicitly... 
        // Actually we need minimum left, then shortest length
        // So: store if not present, or if same left but smaller right (shorter)
        // Or if smaller left index
        if not Map.TryGetValue(Val, Pair) then
        begin
          Pair.Left := I - 1;  // Convert to 0-indexed
          Pair.Right := J - 1;
          Map.Add(Val, Pair);
        end
        else
        begin
          // Prefer minimum left; if same left, prefer shorter (smaller right)
          if (I - 1 < Pair.Left) or 
             ((I - 1 = Pair.Left) and (J - 1 < Pair.Right)) then
          begin
            Pair.Left := I - 1;
            Pair.Right := J - 1;
            Map[Val] := Pair;
          end;
        end;
      end;
    end;

    // Now answer each query
    for I := 0 to QueryCount - 1 do
    begin
      // The value we need: val XOR first = second => val = first XOR second
      Target := Queries[I][0] xor Queries[I][1];

      if Map.TryGetValue(Target, Pair) then
        Result[I] := Pair
      else
      begin
        Result[I].Left := -1;
        Result[I].Right := -1;
      end;
    end;

  finally
    Map.Free;
  end;
end;

// ── Demo harness ──────────────────────────────────────────────
procedure RunExample(const S: string; const Queries: TQueries);
var
  Results: TResultArray;
  I: Integer;
begin
  Results := FindSubstringIndices(S, Queries);
  Write('[');
  for I := 0 to High(Results) do
  begin
    if I > 0 then Write(', ');
    Write('[', Results[I].Left, ',', Results[I].Right, ']');
  end;
  WriteLn(']');
end;

var
  Q1, Q2, Q3: TQueries;
begin
  // Example 1: s = "101101", queries = [[0,5],[1,2]]
  SetLength(Q1, 2);
  Q1[0] := TQuery.Create(0, 5);
  Q1[1] := TQuery.Create(1, 2);
  Write('Example 1: ');
  RunExample('101101', Q1);

  // Example 2: s = "0101", queries = [[12,8]]
  SetLength(Q2, 1);
  Q2[0] := TQuery.Create(12, 8);
  Write('Example 2: ');
  RunExample('0101', Q2);

  // Example 3: s = "1", queries = [[4,5]]
  SetLength(Q3, 1);
  Q3[0] := TQuery.Create(4, 5);
  Write('Example 3: ');
  RunExample('1', Q3);

  ReadLn;
end.
```

*[Tapping the notepad thoughtfully]*

The precomputation pass is where the real story lives — build once, answer many. The 30-bit ceiling? A quiet but effective guard rail. One might wonder if there are further optimizations lurking... there usually are.

## Swift Translation & Insights

Let me share my take on this — I find the problem itself rather interesting. There's something elegant about finding patterns that echo across multiple strings...

```swift
import Foundation

// MARK: - Generate All Substrings
func allSubstrings(_ input: String) -> [String] {
    let chars = Array(input) // Convert to array for index-based access
    var substrings: [String] = []
    let length = chars.count

    for i in 0..<length {
        for j in (i + 1)...length {
            let substring = String(chars[i..<j])
            substrings.append(substring)
        }
    }
    return substrings
}

// MARK: - Find Longest Common Substring
func longestSubstring(_ strings: [String], _ k: Int) -> String? {
    // Guard against empty input — worth thinking about edge cases early
    guard !strings.isEmpty else { return nil }

    var longestStr = ""

    for s in strings {
        for substr in allSubstrings(s) {
            // Count how many strings contain this substring
            let count = strings.filter { $0.contains(substr) }.count

            if count >= k && substr.count > longestStr.count {
                longestStr = substr
            }
        }
    }

    // Return nil subtly signals "nothing meaningful found"
    return longestStr.isEmpty ? nil : longestStr
}

// MARK: - Example Usage
let strings = ["apple", "pineapple", "snapple"]
if let result = longestSubstring(strings, 2) {
    print("Longest shared substring: \(result)")
} else {
    print("No common substring found")
}
```

