// models/blogPost.js
const mongoose = require('mongoose');

const blogPostSchema = new mongoose.Schema(
  {
    title: {
      type: String,
      required: [true, 'A post without a title... interesting but problematic'],
      trim: true,
      maxlength: [100, 'Perhaps a more concise title?'],
    },
    text: {
      type: String,
      required: [true, 'Content matters'],
      trim: true,
    },
    author: {
      type: String,
      required: [true, 'Someone should own this'],
      trim: true,
    },
  },
  {
    timestamps: true, // quietly tracks creation and updates
    toJSON: { virtuals: true },
  }
);

// A subtle enhancement — search might matter later
blogPostSchema.index({ author: 1, createdAt: -1 });

module.exports = mongoose.model('BlogPost', blogPostSchema);
