## The Routes — Where Flexibility Shines

```javascript
// routes/posts.js
const express = require('express');
const router = express.Router();
const BlogPost = require('../models/blogPost');

/**
 * GET /api/posts
 * Retrieves all posts — with optional filtering hints built in
 * One might notice the query params... they're there for a reason
 */
router.get('/', async (req, res, next) => {
  try {
    const {
      author,           // filter by author if you're curious
      limit = 10,       // sensible default
      page = 1,         // because infinite scrolling has its costs
      sort = '-createdAt' // newest first, naturally
    } = req.query;

    // Build query organically
    const query = {};
    if (author) query.author = new RegExp(author, 'i'); // flexible matching

    const posts = await BlogPost.find(query)
      .sort(sort)
      .limit(parseInt(limit))
      .skip((parseInt(page) - 1) * parseInt(limit))
      .select('title text author createdAt'); // explicit is elegant

    const total = await BlogPost.countDocuments(query);

    res.status(200).json({
      status: 'success',
      results: posts.length,
      pagination: {
        total,
        page: parseInt(page),
        pages: Math.ceil(total / limit),
      },
      data: { posts },
    });
  } catch (err) {
    next(err); // trust the error handler
  }
});

/**
 * GET /api/posts/:id
 * One post in particular
 */
router.get('/:id', async (req, res, next) => {
  try {
    const post = await BlogPost.findById(req.params.id);

    if (!post) {
      return res.status(404).json({
        status: 'fail',
        message: "That post seems to have wandered off...",
      });
    }

    res.status(200).json({
      status: 'success',
      data: { post },
    });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/posts
 * Bring something new into the world
 */
router.post('/', async (req, res, next) => {
  try {
    const { title, text, author } = req.body;

    const newPost = await BlogPost.create({ title, text, author });

    res.status(201).json({
      status: 'success',
      data: { post: newPost },
    });
  } catch (err) {
    next(err);
  }
});

/**
 * PATCH /api/posts/:id
 * Refine, don't rewrite — unless you want to
 */
router.patch('/:id', async (req, res, next) => {
  try {
    const post = await BlogPost.findByIdAndUpdate(
      req.params.id,
      req.body,
      {
        new: true,           // return the updated version
        runValidators: true, // keep things honest
      }
    );

    if (!post) {
      return res.status(404).json({
        status: 'fail',
        message: 'Nothing found to update...',
      });
    }

    res.status(200).json({
      status: 'success',
      data: { post },
    });
  } catch (err) {
    next(err);
  }
});

/**
 * DELETE /api/posts/:id
 * Sometimes letting go is necessary
 */
router.delete('/:id', async (req, res, next) => {
  try {
    const post = await BlogPost.findByIdAndDelete(req.params.id);

    if (!post) {
      return res.status(404).json({
        status: 'fail',
        message: 'Already gone, it seems...',
      });
    }

    res.status(204).json({
      status: 'success',
      data: null,
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;
```

