## The Error Handler — Quietly Essential

```javascript
// middleware/errorHandler.js
const errorHandler = (err, req, res, next) => {
  let status = err.statusCode || 500;
  let message = err.message || 'Something unexpected happened...';

  // MongoDB validation errors deserve a cleaner response
  if (err.name === 'ValidationError') {
    status = 400;
    message = Object.values(err.errors)
      .map(e => e.message)
      .join(', ');
  }

  // Cast errors — usually a malformed ID
  if (err.name === 'CastError') {
    status = 400;
    message = `That doesn't look like a valid ID...`;
  }

  res.status(status).json({
    status: 'error',
    message,
    // only reveal the stack in development — some things are private
    ...(process.env.NODE_ENV === 'development' && { stack: err.stack }),
  });
};

module.exports = errorHandler;
```

