## The Server — Where Everything Converges

```javascript
// server.js
require('dotenv').config();
const express = require('express');
const mongoose = require('mongoose');
const postRoutes = require('./routes/posts');
const errorHandler = require('./middleware/errorHandler');

const app = express();

// Middleware
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Routes — clean and discoverable
app.use('/api/posts', postRoutes);

// A subtle health check — often underrated
app.get('/health', (req, res) => {
  res.status(200).json({ status: 'alive', timestamp: new Date() });
});

// Unhandled routes — worth acknowledging
app.all('*', (req, res) => {
  res.status(404).json({
    status: 'fail',
    message: `Hmm... ${req.originalUrl} doesn't seem to lead anywhere`,
  });
});

// Error handling — always last
app.use(errorHandler);

// Database connection — then server
const startServer = async () => {
  try {
    await mongoose.connect(process.env.MONGO_URI, {
      useNewUrlParser: true,
      useUnifiedTopology: true,
    });

    console.log('✓ MongoDB connection established quietly');

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`✓ Server listening on port ${PORT}...`);
      console.log(`  Perhaps explore /api/posts when ready`);
    });
  } catch (err) {
    console.error('Connection issue worth investigating:', err.message);
    process.exit(1);
  }
};

startServer();
```

